// ***************
// Filename: intc_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of intc: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to intc's logic on named ports, its status
//   comes back on input ports. Interrupt controller: enable, edge / level
//   type, polarity, pending, software set, vector. Generated by
//   ip/scripts/regmap_gen.py from intc_regs.json: edit the JSON and
//   regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "INTC" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 ENABLE      RW   interrupt enable per source, reset 0x0
//     0x14 EDGE_TYPE   RW   1 = edge source (latched in PENDING), 0 = level,
//                       reset 0x0
//     0x18 ACTIVE_LOW  RW   1 = active-low source, reset 0x0
//     0x1C PENDING     CMD  pending sources; write 1 to clear latched (edge)
//                       bits
//     0x20 SOFT_SET    WO   write 1s: set those sources pending (software
//                       interrupt)
//     0x24 VECTOR      RO   highest-priority (lowest index) pending enabled
//                       source
//                       [4:0] ID: source number
//                       [31] VALID: a source is pending and enabled
//     0x28 MASKED      RO   PENDING AND ENABLE
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-20
module intc_regs #(
  parameter int NUM_IRQ = 16  // number of sources (1..32)
) (
  input  logic               aclk,            // clock
  input  logic               aresetn,         // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: intc_regs_if.regs (src/include/intc_regs_if.sv) {enable_o=cfg_enable enable_wr_o=cfg_enable_wr edge_type_o=cfg_edge_type edge_type_wr_o=cfg_edge_type_wr active_low_o=cfg_active_low active_low_wr_o=cfg_active_low_wr pending_i=sts_pending pending_o=cfg_pending pending_wr_o=cfg_pending_wr soft_set_o=cfg_soft_set soft_set_wr_o=cfg_soft_set_wr vector_i=sts_vector masked_i=sts_masked}
  intc_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [NUM_IRQ-1:0] enable_o;
  logic enable_wr_o;
  logic [NUM_IRQ-1:0] edge_type_o;
  logic edge_type_wr_o;
  logic [NUM_IRQ-1:0] active_low_o;
  logic active_low_wr_o;
  logic [NUM_IRQ-1:0] pending_i;
  logic [NUM_IRQ-1:0] pending_o;
  logic pending_wr_o;
  logic [NUM_IRQ-1:0] soft_set_o;
  logic soft_set_wr_o;
  logic [32-1:0] vector_i;
  logic [NUM_IRQ-1:0] masked_i;
  assign r.cfg_enable = enable_o;
  assign r.cfg_enable_wr = enable_wr_o;
  assign r.cfg_edge_type = edge_type_o;
  assign r.cfg_edge_type_wr = edge_type_wr_o;
  assign r.cfg_active_low = active_low_o;
  assign r.cfg_active_low_wr = active_low_wr_o;
  assign pending_i = r.sts_pending;
  assign r.cfg_pending = pending_o;
  assign r.cfg_pending_wr = pending_wr_o;
  assign r.cfg_soft_set = soft_set_o;
  assign r.cfg_soft_set_wr = soft_set_wr_o;
  assign vector_i = r.sts_vector;
  assign masked_i = r.sts_masked;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "INTC";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_ENABLE = 8'h10;
  localparam logic [7:0] A_EDGE_TYPE = 8'h14;
  localparam logic [7:0] A_ACTIVE_LOW = 8'h18;
  localparam logic [7:0] A_PENDING = 8'h1C;
  localparam logic [7:0] A_SOFT_SET = 8'h20;
  localparam logic [7:0] A_VECTOR = 8'h24;
  localparam logic [7:0] A_MASKED = 8'h28;
  localparam int MAP_WORDS = 11;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] enable_q;
  logic [31:0] edge_type_q;
  logic [31:0] active_low_q;
  logic [31:0] pending_q;
  logic [31:0] soft_set_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      enable_q <= 32'h0;
      enable_wr_o <= 1'b0;
      edge_type_q <= 32'h0;
      edge_type_wr_o <= 1'b0;
      active_low_q <= 32'h0;
      active_low_wr_o <= 1'b0;
      pending_q <= '0;
      pending_wr_o <= 1'b0;
      soft_set_q <= '0;
      soft_set_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_VECTOR || wa == A_MASKED);   // writes to read-only words: SLVERR
      begin
        enable_wr_o <= wr_en && wa == A_ENABLE;
        if (wr_en && wa == A_ENABLE) enable_q <= (enable_q & ~wmask) | (wr_data & wmask);
      end
      begin
        edge_type_wr_o <= wr_en && wa == A_EDGE_TYPE;
        if (wr_en && wa == A_EDGE_TYPE) edge_type_q <= (edge_type_q & ~wmask) | (wr_data & wmask);
      end
      begin
        active_low_wr_o <= wr_en && wa == A_ACTIVE_LOW;
        if (wr_en && wa == A_ACTIVE_LOW) active_low_q <= (active_low_q & ~wmask) | (wr_data & wmask);
      end
      begin
        pending_wr_o <= wr_en && wa == A_PENDING;
        if (wr_en && wa == A_PENDING) pending_q <= (pending_q & ~wmask) | (wr_data & wmask);
      end
      begin
        soft_set_wr_o <= wr_en && wa == A_SOFT_SET;
        if (wr_en && wa == A_SOFT_SET) soft_set_q <= (soft_set_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign enable_o = enable_q[NUM_IRQ-1:0];
  assign edge_type_o = edge_type_q[NUM_IRQ-1:0];
  assign active_low_o = active_low_q[NUM_IRQ-1:0];
  assign pending_o = pending_q[NUM_IRQ-1:0];
  assign soft_set_o = soft_set_q[NUM_IRQ-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_ENABLE: rd_data = 32'(enable_q[NUM_IRQ-1:0]);
      A_EDGE_TYPE: rd_data = 32'(edge_type_q[NUM_IRQ-1:0]);
      A_ACTIVE_LOW: rd_data = 32'(active_low_q[NUM_IRQ-1:0]);
      A_PENDING: rd_data = 32'(pending_i);
      A_VECTOR: rd_data = 32'(vector_i);
      A_MASKED: rd_data = 32'(masked_i);
      default: begin
      end
    endcase
  end
endmodule
